"""Unit, split-integrity, and provenance tests for the machine learning pipeline."""

from __future__ import annotations

import json
from pathlib import Path
import hashlib
import numpy as np
import pandas as pd
import pytest

from feature_extraction.extract_features import SCHEMA_COLUMNS
from ml.dataset import (
    TRAIN_SEEDS,
    TEST_SEEDS,
    build_composite_run,
    partition_by_seed,
    sha256_file,
)


@pytest.fixture(scope="module")
def dataset_artifacts():
    """Load on-disk dataset artifacts generated by scripts/build_dataset.py."""
    data_dir = Path("data")
    master_path = data_dir / "master.csv"
    train_path = data_dir / "train.csv"
    test_path = data_dir / "test.csv"
    manifest_path = data_dir / "dataset_manifest.json"

    assert master_path.exists(), f"Missing {master_path}. Run scripts/build_dataset.py first."
    assert train_path.exists(), f"Missing {train_path}. Run scripts/build_dataset.py first."
    assert test_path.exists(), f"Missing {test_path}. Run scripts/build_dataset.py first."
    assert manifest_path.exists(), f"Missing {manifest_path}. Run scripts/build_dataset.py first."

    master_df = pd.read_csv(master_path)
    train_df = pd.read_csv(train_path)
    test_df = pd.read_csv(test_path)
    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    return {
        "master": master_df,
        "train": train_df,
        "test": test_df,
        "manifest": manifest,
        "paths": {
            "master": master_path,
            "train": train_path,
            "test": test_path,
            "manifest": manifest_path,
        },
    }


def test_split_seed_disjointness(dataset_artifacts):
    """Verify manifest records train seeds [42, 43] and test seeds [44] with zero overlap."""
    manifest = dataset_artifacts["manifest"]
    train_seeds = manifest["splits"]["train"]["seeds"]
    test_seeds = manifest["splits"]["test"]["seeds"]

    assert train_seeds == list(TRAIN_SEEDS)
    assert test_seeds == list(TEST_SEEDS)
    assert set(train_seeds).isdisjoint(set(test_seeds)), "Train and test seeds must be strictly disjoint!"


def test_split_count_conservation(dataset_artifacts):
    """Verify row conservation: len(train) + len(test) == len(master), both non-empty."""
    master = dataset_artifacts["master"]
    train = dataset_artifacts["train"]
    test = dataset_artifacts["test"]

    assert len(train) > 0, "Train split is empty"
    assert len(test) > 0, "Test split is empty"
    assert len(train) + len(test) == len(master), (
        f"Row count mismatch: len(train)={len(train)} + len(test)={len(test)} != len(master)={len(master)}"
    )


def test_train_test_schema_exact(dataset_artifacts):
    """Verify train and test columns equal SCHEMA_COLUMNS exactly; master has SCHEMA_COLUMNS + ['seed']."""
    master = dataset_artifacts["master"]
    train = dataset_artifacts["train"]
    test = dataset_artifacts["test"]

    assert list(train.columns) == SCHEMA_COLUMNS, "Train schema does not match canonical SCHEMA_COLUMNS"
    assert list(test.columns) == SCHEMA_COLUMNS, "Test schema does not match canonical SCHEMA_COLUMNS"
    assert list(master.columns) == SCHEMA_COLUMNS + ["seed"], "Master schema does not match SCHEMA_COLUMNS + ['seed']"


def test_split_no_nan_inf(dataset_artifacts):
    """Verify numeric feature columns in train and test splits contain no NaN or inf values."""
    train = dataset_artifacts["train"]
    test = dataset_artifacts["test"]

    numeric_cols = [c for c in SCHEMA_COLUMNS if c != "label"]
    for split_name, df in [("train", train), ("test", test)]:
        for col in numeric_cols:
            vals = df[col].to_numpy(dtype=float)
            assert np.all(np.isfinite(vals)), f"Found NaN or Inf in {split_name} split column '{col}'"


def test_train_has_attack_class_rows(dataset_artifacts):
    """Verify train and test splits contain both 'Blackhole' and 'Normal' labels."""
    train = dataset_artifacts["train"]
    test = dataset_artifacts["test"]

    for split_name, df in [("train", train), ("test", test)]:
        labels = set(df["label"].unique())
        assert "Blackhole" in labels, f"{split_name} split missing 'Blackhole' label"
        assert "Normal" in labels, f"{split_name} split missing 'Normal' label"


def test_manifest_checksums_match(dataset_artifacts):
    """Verify SHA-256 digests and row counts in manifest match the actual files on disk."""
    manifest = dataset_artifacts["manifest"]
    paths = dataset_artifacts["paths"]

    for fname, info in manifest["files"].items():
        key = fname.replace(".csv", "")
        file_path = paths[key]
        actual_sha = sha256_file(file_path)
        actual_rows = len(pd.read_csv(file_path))

        assert info["sha256"] == actual_sha, f"SHA-256 mismatch for {fname}: manifest={info['sha256']}, actual={actual_sha}"
        assert info["rows"] == actual_rows, f"Row count mismatch for {fname}: manifest={info['rows']}, actual={actual_rows}"


def test_manifest_class_distributions(dataset_artifacts):
    """Verify manifest class distributions match actual value_counts for train and test splits."""
    manifest = dataset_artifacts["manifest"]
    train = dataset_artifacts["train"]
    test = dataset_artifacts["test"]

    for split_name, df in [("train", train), ("test", test)]:
        actual_dist = {str(k): int(v) for k, v in df["label"].value_counts().items()}
        manifest_dist = manifest["splits"][split_name]["class_distribution"]
        assert actual_dist == manifest_dist, (
            f"Class distribution mismatch for {split_name}: manifest={manifest_dist}, actual={actual_dist}"
        )


def test_split_deterministic_rebuild(tmp_path, dataset_artifacts):
    """Verify deterministic build of single run, and re-partitioning master matches train/test exactly."""
    # 1. Deterministic rebuild of seed 42 run (short duration for speed)
    scenario_path = "scenarios/e3_blackhole_onset_30n.json"
    run1 = build_composite_run(
        seed=42,
        scenario_path=scenario_path,
        trace_dir=tmp_path / "t1",
        window_size=5.0,
        step_size=1.0,
        warmup=0.0,
        duration=20.0,
    )
    run2 = build_composite_run(
        seed=42,
        scenario_path=scenario_path,
        trace_dir=tmp_path / "t2",
        window_size=5.0,
        step_size=1.0,
        warmup=0.0,
        duration=20.0,
    )
    assert run1.equals(run2), "Repeated simulation run for seed 42 did not produce identical feature DataFrame!"

    # 2. Partition on-disk master and verify equality to on-disk train and test
    master_df = dataset_artifacts["master"]
    rebuilt_train, rebuilt_test = partition_by_seed(master_df)

    assert rebuilt_train.equals(dataset_artifacts["train"]), "Partitioned train does not match on-disk train.csv"
    assert rebuilt_test.equals(dataset_artifacts["test"]), "Partitioned test does not match on-disk test.csv"


def test_train_class_weight_balanced():
    """Verify every classifier pipeline step uses class_weight='balanced'."""
    from ml.train import build_pipelines

    pipelines = build_pipelines()
    for name, (pipe, _) in pipelines.items():
        clf = pipe.named_steps["clf"]
        assert hasattr(clf, "class_weight"), f"{name} clf step missing class_weight attribute"
        assert clf.class_weight == "balanced", f"{name} class_weight is not 'balanced'"


def test_train_primary_scorer_orientation():
    """Verify scorer strictly evaluates Blackhole as positive class (0.0 when predicting Normal)."""
    from sklearn.dummy import DummyClassifier
    from sklearn.pipeline import Pipeline
    from sklearn.preprocessing import StandardScaler
    from ml.train import build_scoring

    feature_cols = [c for c in SCHEMA_COLUMNS if c != "label"]
    # 20 Normal, 5 Blackhole rows
    X_syn = pd.DataFrame(np.ones((25, len(feature_cols))), columns=feature_cols)
    y_syn = pd.Series(["Normal"] * 20 + ["Blackhole"] * 5)

    dummy = Pipeline([
        ("scaler", StandardScaler()),
        ("clf", DummyClassifier(strategy="constant", constant="Normal")),
    ])
    dummy.fit(X_syn, y_syn)

    scorer = build_scoring()["f1_blackhole"]
    score = scorer(dummy, X_syn, y_syn)
    assert score == 0.0, f"Expected 0.0 for all-Normal prediction with Blackhole pos_label, got {score}"


def test_train_smoke_deterministic(dataset_artifacts):
    """Verify single-combo fits for all candidates succeed and are deterministic."""
    from ml.train import (
        build_pipelines,
        fit_pipeline,
        stratified_subsample,
    )
    from sklearn.svm import SVC

    train_df = dataset_artifacts["train"]
    feature_cols = [c for c in SCHEMA_COLUMNS if c != "label"]
    X = train_df[feature_cols]
    y = train_df["label"]

    X_sub, y_sub = stratified_subsample(X, y, n=2000, random_state=0)
    pipelines = build_pipelines()

    single_combo_grids = {
        "random_forest": {"clf__n_estimators": [50], "clf__max_depth": [8]},
        "decision_tree": {"clf__max_depth": [8], "clf__min_samples_split": [2]},
        "svm": {"clf__C": [10], "clf__gamma": [0.01]},
    }

    for name in ["random_forest", "decision_tree", "svm"]:
        pipe, _ = pipelines[name]
        grid_params = single_combo_grids[name]

        if name == "svm":
            assert isinstance(pipe.named_steps["clf"], SVC)
            assert pipe.named_steps["clf"].kernel == "rbf"
            assert pipe.named_steps["clf"].class_weight == "balanced"

        grid1 = fit_pipeline(pipe, grid_params, X_sub, y_sub, cv=5)
        grid2 = fit_pipeline(pipe, grid_params, X_sub, y_sub, cv=5)

        assert grid1.best_score_ is not None
        assert grid2.best_score_ is not None
        np.testing.assert_allclose(
            grid1.cv_results_["mean_test_f1_blackhole"],
            grid2.cv_results_["mean_test_f1_blackhole"],
            err_msg=f"Non-deterministic CV scores detected for {name}",
        )


def test_train_no_test_file_access():
    """Structural guard for T-03-02: verify ml/train.py never accesses held-out or master files."""
    train_source_path = Path("ml/train.py")
    assert train_source_path.exists()
    content = train_source_path.read_text(encoding="utf-8")

    forbidden_files = ["test.csv", "master.csv"]
    for f in forbidden_files:
        assert f not in content, f"ml/train.py contains forbidden reference to '{f}'!"

